  function localDay(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
  function tripStatus(r,today=localDay()){
    if(!r.trip)return '';
    if(r.trip.end<today)return 'Data trascorsa: questa partenza non è presentata come prenotabile.';
    if(r.trip.start<today)return 'Viaggio già iniziato: questa partenza non è presentata come prenotabile.';
    return 'Programma pubblicato: conferma della partenza e disponibilità dei posti da chiedere all’organizzatore.';
  }
  function inJourney(r,id,mode=''){
    if(!id||id==='tutte')return true;
    const fields=r.fields||[],g=r.groups||[];
    const activities=r.mode==='ballo'||fields.some(f=>/Attività culturali e artistiche|Sport e tempo libero|Sport e socialità/.test(f));
    const culture=activities||['musei','parchi','ristoro'].includes(r.mode);
    if(id==='amicizie')return mode==='social'?false:mode==='app'?r.mode==='app':mode==='territorio'?g.includes('csaq')||activities:r.journey==='amicizie'||g.includes('csaq')||activities;
    if(id==='centri')return g.includes('csaq');
    if(id==='cultura')return culture&&(!mode||(mode==='altre'?!['ballo','musei','parchi','ristoro'].includes(r.mode):r.mode===mode));
    if(id==='giochi')return r.journey==='giochi'&&(!mode||r.mode===mode);
    if(id==='turismo')return r.journey==='turismo'&&(!mode||r.mode===mode);
    if(id==='solidarieta')return g.includes('volontariato');
    if(id==='quartiere')return g.includes('comitati')||fields.includes('Attivismo civico e partecipazione');
    if(id==='spazi')return fields.includes('Rigenerazione spazi urbani e cura del verde pubblico')||fields.includes('Orti urbani e agricoltura sociale');
    if(id==='reti')return g.includes('volontariato')||fields.includes('Reti di prossimità');
    if(id==='ascolto')return fields.includes('Ascolto e sostegno emotivo');
    return false;
  }
  function filter(records, options={}) {
    const term=(options.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it');
    return records.filter(r=>inJourney(r,options.journey,options.mode)&&(!(options.journey==='turismo'&&r.trip&&!options.past)||r.trip.start>=(options.today||localDay()))&&(!options.group||r.groups.includes(options.group))&&(!options.municipio||r.municipalities.includes(options.municipio))&&(!options.neighborhood||r.neighborhood===options.neighborhood)&&(!options.field||r.fields.includes(options.field))&&[r.name,r.description,...r.fields].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it').includes(term)).sort((a,b)=>a.name.localeCompare(b.name,'it'));
  }
