      if(['ballo','musei','parchi','ristoro','presenza','ludoteche'].includes(r.mode)){rows.unshift(['Indirizzo di riferimento',r.operationalAddress]);if(r.neighborhood)rows.unshift(['Quartiere dichiarato',r.neighborhood]);}
      if(r.runts)rows.push(['Codice fiscale',r.runts.taxCode],['Sezione RUNTS',r.runts.section],['Repertorio e iscrizione',r.runts.number+' · '+r.runts.registeredAt]);
